package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.collaboration.feedbackretraction.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class FeedbackRetractionStoreIntegrationTest {
 SubmissionFeedbackStoreIntegrationTest f;FeedbackRetractionStore store;SubmissionFeedbackStore.Feedback feedback;
 @BeforeEach void setup(){f=new SubmissionFeedbackStoreIntegrationTest();f.setup();feedback=f.change(0,1,"Original feedback <script>\n원문");store=new FeedbackRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());}
 FeedbackRetractionStore.Retraction change(long target,long expected,String state,String reason){return store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,target,expected,new FeedbackRetractionInput(state,reason),f.f.f.trace);}
 FeedbackRetractionStore.View get(UUID actor,boolean owner,long target){return store.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),actor,owner,target);}
 FeedbackRetractionStore.History history(long target,long before,int limit){return store.history(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,target,before,limit);}
 void status(int code,org.junit.jupiter.api.function.Executable action){f.status(code,action);}
 @Test void absenceDoesNotCreateAndCannotRestoreOrDiscoverOtherAuthors(){assertNull(get(f.f.author,false,1).retraction());assertFalse(get(f.f.author,false,1).canWrite());assertTrue(get(f.f.f.owner,true,1).canWrite());assertTrue(history(1,Long.MAX_VALUE,5).items().isEmpty());status(409,()->change(1,0,"RESTORED","Nothing retracted"));status(404,()->get(f.f.f.ids.next(),false,1));assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM feedback_retraction WHERE feedback_id=?",Integer.class,feedback.feedbackId()));}
 @Test void currentRevisionAndFullProtobufPinExactFeedbackAndOriginalSource()throws Exception{var v=change(1,0,"RETRACTED","Incorrect opinion <script>\n철회 이유");assertEquals(7,v.retractionId().version());assertEquals(feedback.feedbackId(),v.feedbackId());assertEquals(1,v.feedbackVersion());assertEquals(1,v.submissionVersion());assertEquals(2,v.assignmentVersion());assertEquals(f.f.author,v.authorId());assertEquals(f.f.f.owner,v.actorId());assertEquals("AUTHOR_AND_OWNER",v.audience());assertEquals(v,history(1,Long.MAX_VALUE,5).items().getFirst().snapshot());var e=FeedbackRetractionEnvelopeV1.parseFrom(f.f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.retractionId()));var p=FeedbackRetractionSnapshotV1.parseFrom(e.getPayload());assertEquals("FeedbackRetracted",e.getEventType());assertEquals("FeedbackRetraction",e.getAggregateType());assertEquals(f.f.f.trace,e.getTraceId());assertEquals(f.f.space.toString(),e.getSpaceId());assertEquals(f.f.f.owner.toString(),e.getActorId());assertEquals(v.reason(),p.getReason());assertEquals(feedback.feedbackId().toString(),p.getFeedbackId());assertEquals(1,p.getFeedbackVersion());assertEquals(v.state(),p.getState());assertEquals("AUTHOR_AND_OWNER",p.getAudience());}
 @Test void independentVersionNoOpAndRestorationKeepAudit(){var v=change(1,0,"RETRACTED","Reason");assertEquals(v,change(1,1,"RETRACTED","Reason"));status(412,()->change(1,0,"RETRACTED","Reason"));var restored=change(1,1,"RESTORED","Reviewed again");assertEquals(v.retractionId(),restored.retractionId());assertEquals(v.createdAt(),restored.createdAt());assertEquals(2,restored.version());assertEquals("RESTORED",restored.state());assertEquals("RETRACTED",history(1,2,5).items().getFirst().snapshot().state());assertEquals(2,f.f.events(v.retractionId()));}
 @Test void newFeedbackVersionHasIndependentDefaultAndOldRetractionSurvives(){var old=change(1,0,"RETRACTED","First version withdrawn");var corrected=f.change(1,1,"New explicitly shared comment");assertNull(get(f.f.author,false,2).retraction());assertEquals(old,get(f.f.author,false,1).retraction());var second=change(2,0,"RETRACTED","Second version withdrawn");assertNotEquals(old.retractionId(),second.retractionId());assertEquals(2,second.feedbackVersion());assertEquals(corrected,f.get(f.f.author,false).feedback());assertEquals(1,history(1,Long.MAX_VALUE,5).items().size());assertEquals(1,history(2,Long.MAX_VALUE,5).items().size());}
 @Test void originalFeedbackSubmissionAndRequestRemainUnchanged(){var requestStore=new ResubmissionRequestStore(f.f.f.source,f.f.parent.store,Clock.systemUTC());var request=requestStore.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,0,new ResubmissionRequestInput("REQUEST","Please revise",1,2),f.f.f.trace);var assignment=f.f.parent.store.get(f.f.group,f.f.space,f.f.study,f.f.assignment);change(1,0,"RETRACTED","No longer endorse this opinion");assertEquals(feedback,f.get(f.f.author,false).feedback());assertEquals(feedback,f.history(Long.MAX_VALUE,5).items().getFirst().snapshot());assertEquals(feedback,f.change(1,1,feedback.content()));assertEquals("RETRACTED",get(f.f.author,false,1).retraction().state());assertEquals(f.answer,f.f.store.mine(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.author,true).submission());assertEquals(request,requestStore.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false).request());assertEquals(assignment,f.f.parent.store.get(f.f.group,f.f.space,f.f.study,f.f.assignment));assertEquals(1,f.f.events(feedback.feedbackId()));}
 @Test void resubmissionKeepsOldFeedbackMarkerAndCorrectImmutableBasis(){var v=change(1,0,"RETRACTED","Old opinion");f.f.submit(f.f.f.key(),1,2,"New answer");f.change(1,2,"Comment on new answer");assertEquals(v,get(f.f.author,false,1).retraction());var next=change(2,0,"RETRACTED","New opinion");assertEquals(2,next.submissionVersion());assertEquals(1,history(1,Long.MAX_VALUE,5).items().getFirst().snapshot().submissionVersion());}
 @Test void closedAllowsAnnotationsAndRetiredAssignmentFreezesWithHistory(){f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);var v=change(1,0,"RETRACTED","After close");assertTrue(get(f.f.f.owner,true,1).canWrite());f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);assertFalse(get(f.f.f.owner,true,1).canWrite());status(409,()->change(1,1,"RESTORED","After archive"));assertEquals(v,history(1,Long.MAX_VALUE,5).items().getFirst().snapshot());}
 @Test void retiredStudyFreezesEvenAnOpenAssignment(){var v=change(1,0,"RETRACTED","Before archive");f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);assertFalse(get(f.f.f.owner,true,1).canWrite());status(409,()->change(1,1,"RESTORED","Frozen"));assertEquals(v,get(f.f.author,false,1).retraction());}
 @Test void exactScopeAndImmutableTargetPreventPeersOrMissingVersionAccess(){var peer=f.f.f.ids.next();status(404,()->store.history(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),peer,false,1,Long.MAX_VALUE,5));status(404,()->get(f.f.f.owner,true,2));status(400,()->get(f.f.f.owner,true,0));status(404,()->store.get(f.f.f.ids.next(),f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,true,1));status(404,()->store.get(f.f.group,f.f.f.ids.next(),f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,true,1));status(404,()->store.change(f.f.group,f.f.space,f.f.study,f.f.f.ids.next(),f.answer.submissionId(),f.f.f.owner,1,0,new FeedbackRetractionInput("RETRACTED","Wrong parent"),f.f.f.trace));}
 @Test void paginatedStateHistoryPreservesAllReasons(){for(int n=0;n<7;n++)change(1,n,n%2==0?"RETRACTED":"RESTORED","Reason "+n);var first=history(1,Long.MAX_VALUE,5);assertEquals(List.of(7L,6L,5L,4L,3L),first.items().stream().map(FeedbackRetractionStore.Revision::version).toList());assertEquals(3L,first.nextBefore());var second=history(1,first.nextBefore(),5);assertEquals(List.of(2L,1L),second.items().stream().map(FeedbackRetractionStore.Revision::version).toList());assertNull(second.nextBefore());}
 @Test void concurrentInitialAndExistingMarkersHaveOneWinner()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){for(int round=0;round<2;round++){long base=round;var barrier=new CyclicBarrier(2);var futures=new ArrayList<Future<Boolean>>();for(int n=0;n<2;n++){String reason="Reason "+round+"/"+n;futures.add(pool.submit(()->{barrier.await();try{change(1,base,"RETRACTED",reason);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));}assertNotEquals(futures.get(0).get(20,TimeUnit.SECONDS),futures.get(1).get(20,TimeUnit.SECONDS));}}}
 @Test void outboxFailureRollsBackInitialAndExistingMarker(){String name="retraction_fail_"+f.answer.submissionId().toString().replace("-","");String check=" CHECK(aggregatetype<>'feedback-retraction' OR trace_id<>'"+f.f.f.trace+"') NOT VALID";f.f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(1,0,"RETRACTED","Fail initial"));assertNull(get(f.f.author,false,1).retraction());assertTrue(history(1,Long.MAX_VALUE,5).items().isEmpty());}finally{f.f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}var v=change(1,0,"RETRACTED","Saved");f.f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(1,1,"RESTORED","Fail restoration"));assertEquals(v,get(f.f.author,false,1).retraction());assertEquals(1,history(1,Long.MAX_VALUE,5).items().size());assertEquals(1,f.f.events(v.retractionId()));}finally{f.f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}}
 @Test void localForeignKeysRejectWrongFeedbackTargetAndDuplicateAnnotation(){var v=change(1,0,"RETRACTED","Reason");assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.f.jdbc.update("UPDATE feedback_retraction SET feedback_version=999999 WHERE retraction_id=?",v.retractionId()));assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.f.jdbc.update("INSERT INTO feedback_retraction SELECT ?,feedback_id,feedback_version,submission_id,assignment_id,study_id,group_id,space_id,author_id,version,snapshot FROM feedback_retraction WHERE retraction_id=?",f.f.f.ids.next(),v.retractionId()));assertEquals(v,get(f.f.author,false,1).retraction());}
}
